    """A local source dir and an rclone alias remote pointing at a dest dir."""
    src = tmp_path / "src"
    dst = tmp_path / "dst"
    src.mkdir()
    dst.mkdir()
    conf = tmp_path / "rclone.conf"
    conf.write_text(f"[dst]\ntype = alias\nremote = {dst}\n")
    return conf, src, dst


